pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant NOT_ZERO = address(0x1);
    function setUp() public {
        c = new C(address(this), address(this));
        // Setup: create a game item so minting works, and mint a token to a known account
        vm.prank(address(this));
        c.instantiateNeuronContract(address(new NeuronMock()));
        vm.prank(address(this));
        c.createGameItem("Sword", "ipfs://sword", false, true, 0, 0, 1);
        // Ensure the known account has balance by minting
        vm.prank(address(this));
        c.mint(NOT_ZERO, 1);
    }

    function testFuzz_property(uint256 dummy) public {
        // Fuzz parameter forces the fuzzer to explore various states,
        // but we always test the property with a fixed non-zero account.
        // We restrict dummy to keep the domain wide.
        vm.assume(dummy < type(uint256).max);

        address[] memory accounts = new address[](1);
        accounts[0] = NOT_ZERO;
        uint256[] memory ids = new uint256[](1);
        ids[0] = 0;

        uint256[] memory batchBalances = c.balanceOfBatch(accounts, ids);

        // The reference C should return the actual balance (non-zero), the mutant returns zero.
        // If the length is 1 and the account holds tokens, the balance must be > 0.
        assertTrue(batchBalances[0] > 0);
    }
}

